"""CX-VA01-0311: independently inspect generated bytes; never regenerate or edit the contract."""
import hashlib
import json
import pathlib
import re
import subprocess

ROOT = pathlib.Path(__file__).resolve().parents[3]
HERE = pathlib.Path(__file__).resolve().parent
D = json.loads((ROOT / 'lab/acceptance/obligations.json').read_text())


def sha(raw):
    return hashlib.sha256(raw).hexdigest()


def rows(path):
    out = {}
    for line in path.read_text().splitlines():
        m = re.match(r'^\| (Q\d+[a-z])\b([^|]*)\| (.*?) \| (.*?) \|$', line)
        if m:
            out[m[1]] = {'topic': m[2].strip(), 'rule': m[3], 'basis': m[4]}
    return out


def destination(rid):
    return ('continuationRules' if rid.startswith('Q70') else
            'seedRules' if rid.startswith('Q74') else
            'qualificationRun.integrity' if rid.startswith(('Q75', 'Q81')) else
            'recursionRules' if rid.startswith(('Q76', 'Q77')) else
            'datomicRules' if rid.startswith('Q78') else 'exactQueryRules')


def selected_ids():
    return [f'Q{n}{c}' for n, letters in ((70, 'abcdefghijklmno'), (74, 'abcdefg'),
            (75, 'abcdefghij'), (76, 'abcdef'), (77, 'abc'), (78, 'abcd'),
            (79, 'abcd'), (81, 'a')) for c in letters]


def main():
    external = pathlib.Path('/Users/sam/Claude/Projects/triplex-db-2/EXP-O04b-oracle-0.4.2/hashes.0.4.9.txt')
    source = external.read_bytes()
    (HERE / 'hashes.0.4.9-source.txt').write_bytes(source)
    hashes = {line.split()[1]: line.split()[0] for line in source.decode().splitlines()}
    pin = D['oraclePins']['O-REPLAY']
    files = []
    for path, expected in hashes.items():
        live = sha((ROOT / path).read_bytes())
        blob = sha(subprocess.check_output(['git', 'show', f"{pin['commit']}:{path}"], cwd=ROOT))
        files.append({'path': path, 'expected': expected, 'contract': pin['sha256'].get(path),
                      'worktree': live, 'pinnedCommitBlob': blob,
                      'match': expected == live == blob == pin['sha256'].get(path)})
    authority = rows(ROOT / 'lab/acceptance/RULINGS.md')
    original = rows(HERE / 'RULINGS-PENDING-source-snapshot.md')
    mapping = []
    for rid in selected_ids():
        dest = destination(rid)
        value = D
        for key in dest.split('.'):
            value = value[key]
        compiled = next(x for x in D['rulings'] if x['id'] == rid)
        mapping.append({'id': rid, 'generatedPath': dest + '.' + rid,
                        'sameAsAuthoritativeRow': value[rid] == authority[rid],
                        'sameRuleAsOriginalPendingSource': value[rid]['rule'] == original[rid]['rule'],
                        'basisOnlyDifference': [original[rid]['basis'], value[rid]['basis']] if original[rid]['basis'] != value[rid]['basis'] else None,
                        'rulingsIndexMatches': compiled['ruling'] == value[rid]['rule'],
                        'rule': value[rid]['rule']})
    old = json.loads(subprocess.check_output(['git', 'show', 'fcbad6e:lab/acceptance/obligations.json'], cwd=ROOT))
    old_ob = {o['id']: o for o in old['obligations']}
    delta = []
    ignored = {'definitionSha256', 'status', 'lanes'}
    for ob in D['obligations']:
        prev = old_ob[ob['id']]
        fields = {k: {'before': prev.get(k), 'after': ob.get(k)} for k in prev.keys() | ob.keys()
                  if k not in ignored and prev.get(k) != ob.get(k)}
        if fields or [l for l in ob['lanes'] if l != 'datomic-datalog'] != prev['lanes']:
            delta.append({'id': ob['id'], 'oldSurfaceApplicabilitySame': [l for l in ob['lanes'] if l != 'datomic-datalog'] == prev['lanes'], 'changedFields': fields})
    lane = 'datomic-datalog'
    applicable = [o['id'] for o in D['obligations'] if lane in o['lanes']]
    unblocked = [oid for oid in applicable if 'image-unpinned:datomic' not in D['closability']['surfaceBlockers'][lane].get(oid, [])]
    matrix_delta = []
    for prev, cur in zip(old['capabilityMatrix'], D['capabilityMatrix']):
        changed = [c for c in prev['cells'] if prev['cells'][c] != cur['cells'][c]]
        if changed:
            matrix_delta.append({'row': cur['n'], 'changedOldCells': changed})
    result = {'reviewedHead': subprocess.check_output(['git', 'rev-parse', 'HEAD'], cwd=ROOT, text=True).strip(),
              'externalHashTable': {'path': str(external), 'sha256': sha(source)},
              'oraclePin': {k: pin[k] for k in ('commit', 'oracleVersion', 'verifierEntry')},
              'oracleFiles': files, 'all29Match': len(files) == 29 and all(f['match'] for f in files) and set(hashes) == set(pin['sha256']),
              'rulingMapping': mapping, 'oldSurfaceObligationDelta': delta, 'oldMatrixCellDelta': matrix_delta,
              'datomic': {'applicable': applicable, 'notApplicable': [o['id'] for o in D['obligations'] if lane not in o['lanes']],
                          'missingNullImageBlocker': unblocked, 'counts': D['closability']['perSurface'][lane]},
              'pendingInReviewedContract': D['pendingRulings'],
              'additionalPendingInLiveSource': sorted(set(original) - set(authority) - set(D['pendingRulings']['ids']))}
    (HERE / 'audit.json').write_text(json.dumps(result, indent=2, ensure_ascii=False) + '\n')
    print(json.dumps({'all29Match': result['all29Match'], 'rulings': len(mapping),
                      'allRulesMatchSource': all(r['sameAsAuthoritativeRow'] and r['sameRuleAsOriginalPendingSource'] for r in mapping),
                      'datomicApplicable': len(applicable), 'missingNullImageBlocker': unblocked,
                      'oldMatrixCellDelta': matrix_delta}, indent=2))


if __name__ == '__main__':
    main()
